using System.Drawing;
using QuanLyKhachSan.DAL;

namespace QuanLyKhachSan.Forms
{
    public class FrmNhanVien : Form
    {
        readonly NhanVienDAL dal=new(); readonly TextBox ma=new(),ten=new(),sdt=new(),chucvu=new(),taikhoan=new(),matkhau=new(),tim=new(); readonly DataGridView grid=new();
        public FrmNhanVien(){Text="QUẢN LÝ NHÂN VIÊN";Size=new Size(1050,680);StartPosition=FormStartPosition.CenterScreen;Build();LoadData();}
        void Build(){Controls.Add(new Label{Text="QUẢN LÝ NHÂN VIÊN",Font=new Font("Arial",19,FontStyle.Bold),ForeColor=Color.DarkBlue,Location=new Point(350,20),AutoSize=true});Field("Mã nhân viên:",ma,30,85);Field("Họ tên:",ten,30,130);Field("SĐT:",sdt,30,175);Field("Chức vụ:",chucvu,520,85);Field("Tài khoản:",taikhoan,520,130);Field("Mật khẩu:",matkhau,520,175);matkhau.UseSystemPasswordChar=true;Btn("Thêm",30,225,Add);Btn("Sửa",140,225,Edit);Btn("Xóa",250,225,Delete);Btn("Làm mới",360,225,Reset);Controls.Add(new Label{Text="Tìm tên/SĐT/tài khoản:",Location=new Point(520,235),AutoSize=true});tim.SetBounds(690,230,170,28);Controls.Add(tim);Btn("Tìm",870,228,Search);Grid(grid,30,280,960,330);grid.CellClick+=(_,e)=>{if(e.RowIndex>=0){var r=grid.Rows[e.RowIndex];ma.Text=V(r,"MaNV");ten.Text=V(r,"HoTen");sdt.Text=V(r,"SDT");chucvu.Text=V(r,"ChucVu");taikhoan.Text=V(r,"TaiKhoan");matkhau.Text=V(r,"MatKhau");}};}
        void Field(string label,TextBox box,int x,int y){Controls.Add(new Label{Text=label,Location=new Point(x,y+4),Size=new Size(135,24)});box.SetBounds(x+140,y,300,28);Controls.Add(box);}void Btn(string s,int x,int y,EventHandler h){var b=new Button{Text=s,Location=new Point(x,y),Size=new Size(100,34),BackColor=Color.LightSteelBlue};b.Click+=h;Controls.Add(b);}static void Grid(DataGridView g,int x,int y,int w,int h){g.SetBounds(x,y,w,h);g.ReadOnly=true;g.AllowUserToAddRows=false;g.SelectionMode=DataGridViewSelectionMode.FullRowSelect;g.MultiSelect=false;g.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;g.RowHeadersVisible=false;}static string V(DataGridViewRow r,string c)=>r.Cells[c].Value?.ToString()??"";
        void LoadData(){try{grid.DataSource=dal.GetAll();if(grid.Columns["MatKhau"]!=null)grid.Columns["MatKhau"].Visible=false;}catch(Exception ex){MessageBox.Show("Lỗi tải nhân viên: "+ex.Message);}}
        bool Valid(){if(!int.TryParse(ma.Text,out _)||string.IsNullOrWhiteSpace(ten.Text)){MessageBox.Show("Mã nhân viên phải là số và họ tên không được để trống.");return false;}return true;}
        void Add(object? s,EventArgs e){if(Valid())Run(()=>dal.Them(int.Parse(ma.Text),ten.Text.Trim(),sdt.Text.Trim(),chucvu.Text.Trim(),taikhoan.Text.Trim(),matkhau.Text),"Thêm nhân viên");}void Edit(object? s,EventArgs e){if(Valid())Run(()=>dal.Sua(int.Parse(ma.Text),ten.Text.Trim(),sdt.Text.Trim(),chucvu.Text.Trim(),taikhoan.Text.Trim(),matkhau.Text),"Sửa nhân viên");}
        void Delete(object? s,EventArgs e){if(int.TryParse(ma.Text,out int id)&&MessageBox.Show("Xóa nhân viên này?","Xác nhận",MessageBoxButtons.YesNo)==DialogResult.Yes)Run(()=>dal.Xoa(id),"Xóa nhân viên");}void Search(object? s,EventArgs e){try{grid.DataSource=dal.TimKiem(tim.Text.Trim());if(grid.Columns["MatKhau"]!=null)grid.Columns["MatKhau"].Visible=false;}catch(Exception ex){MessageBox.Show(ex.Message);}}void Reset(object? s,EventArgs e){ma.Clear();ten.Clear();sdt.Clear();chucvu.Clear();taikhoan.Clear();matkhau.Clear();tim.Clear();LoadData();}void Run(Action a,string op){try{a();LoadData();MessageBox.Show(op+" thành công.");Reset(null!,EventArgs.Empty);}catch(Exception ex){MessageBox.Show(op+" thất bại: "+ex.Message);}}
    }
}
